class Solution {
public:
    TreeNode* bstFromPreorder(vector<int>& preorder) {
        int idx = 0;
        auto helper = [&](auto& self, int bound) -> TreeNode* {
            if (idx == (int)preorder.size() || preorder[idx] > bound) return nullptr;
            int val = preorder[idx++];
            TreeNode* root = new TreeNode(val);
            root->left = self(self, val);
            root->right = self(self, bound);
            return root;
        };
        return helper(helper, INT_MAX);
    }
};

class Solution {
    private int idx = 0;

    public TreeNode bstFromPreorder(int[] preorder) {
        idx = 0;
        return helper(preorder, Integer.MAX_VALUE);
    }

    private TreeNode helper(int[] preorder, int bound) {
        if (idx == preorder.length || preorder[idx] > bound) return null;
        int val = preorder[idx++];
        TreeNode root = new TreeNode(val);
        root.left = helper(preorder, val);
        root.right = helper(preorder, bound);
        return root;
    }
}

var bstFromPreorder = function(preorder) {
    let idx = 0;
    const helper = (bound) => {
        if (idx === preorder.length || preorder[idx] > bound) return null;
        const val = preorder[idx++];
        const root = new TreeNode(val);
        root.left = helper(val);
        root.right = helper(bound);
        return root;
    };
    return helper(Infinity);
};
